const item = $input.first().json;
const body = item.body || {};
const customerId = String(body.customer_id || '').trim();
const message = String(body.message || '').trim();
const errors = [];
if (!customerId) errors.push('customer_id is required');
if (!message) errors.push('message is required');
if (message.length > 4000) errors.push('message too long (max 4000 characters)');
const tm = String(body.test_mode || '');
const testMode = ['corrupt_first_attempt', 'corrupt_all'].includes(tm) ? tm : null;
return [{ json: {
  valid: errors.length === 0, errors,
  customer_external_id: customerId,
  customer_name: body.customer_name ? String(body.customer_name).trim() : null,
  message,
  message_id: String(body.message_id || $execution.id),
  test_mode: testMode,
  supabase_url: String(item.supabase_url || '').replace(/\/+$/, ''),
  llm_model: item.llm_model
} }];

const ctx = $('Validate Input').first().json;
const cust = $('Upsert Customer').first().json;
const ai = $input.first().json;
const map = { sales: 'sales_agent', support: 'support_agent', billing: 'billing_agent', human: 'human_escalation', unknown: 'human_escalation' };
const LOW_CONFIDENCE = 0.6;
let intent = 'unknown';
let confidence = 0;
let reason = 'classification failed';
try {
  let content = ai.choices[0].message.content;
  content = String(content).replace(/```json|```/g, '').trim();
  const p = JSON.parse(content);
  if (map[p.intent]) intent = p.intent;
  confidence = Math.max(0, Math.min(1, Number(p.confidence) || 0));
  reason = String(p.reason || '').slice(0, 500);
} catch (e) {
  const apiErr = ai.error && ai.error.message ? ai.error.message : e.message;
  reason = 'Classifier output invalid or LLM call failed: ' + apiErr;
  intent = 'unknown';
  confidence = 0;
}
let specialist = map[intent];
if (confidence < LOW_CONFIDENCE && specialist !== 'human_escalation') {
  reason += ' | low confidence -> human_escalation';
  specialist = 'human_escalation';
}
return [{ json: {
  customer_id: cust.id,
  customer_external_id: ctx.customer_external_id,
  message_id: ctx.message_id,
  message: ctx.message,
  supabase_url: ctx.supabase_url,
  llm_model: ctx.llm_model,
  test_mode: ctx.test_mode,
  intent, confidence,
  routing_reason: reason,
  selected_specialist: specialist,
  needs_human: specialist === 'human_escalation'
} }];

const route = $('Parse Intent & Route').first().json;
const ids = { sales_agent: 'YOUR_SALES_AGENT_WORKFLOW_ID', support_agent: 'YOUR_SUPPORT_AGENT_WORKFLOW_ID', billing_agent: 'YOUR_BILLING_AGENT_WORKFLOW_ID' };
const spec = route.selected_specialist;
return [{ json: { customer_id: route.customer_id, message: route.message, intent: route.intent, memory: $('Build Memory Context').first().json.memory_text || '', context: '', attempt: 1, specialist: spec, workflow_id: ids[spec] } }];

const j = $input.first().json || {};
const spec = $('Prepare Specialist Call 1').first().json.specialist;
const agent = String(spec).replace('_agent', '');
let sr;
if (typeof j.success === 'boolean' && 'response' in j) { sr = j; }
else { const e = j.error || j; const msg = String(e.message || e.description || JSON.stringify(e)).slice(0, 500);
  sr = { success: false, response: null, confidence: 0, data: {}, needs_human: true, error: 'specialist_call_failed: ' + msg, agent: agent }; }
return [{ json: { attempt: 1, specialist_result: sr } }];

// TEST-ONLY component: active only when the request contains test_mode. Used to prove that the reviewer catches bad answers.
const st = $input.first().json;
const mode = $('Parse Intent & Route').first().json.test_mode;
const sr = JSON.parse(JSON.stringify(st.specialist_result));
let corrupted = false;
if (sr.success && sr.response && (mode === 'corrupt_all' || (mode === 'corrupt_first_attempt' && st.attempt === 1))) {
  sr.response += '\n\nSpecial offer: 30% discount on all orders today and free express shipping!';
  sr.data = sr.data || {}; sr.data.test_corrupted = true; corrupted = true;
}
return [{ json: { attempt: st.attempt, specialist_result: sr, test_corrupted: corrupted } }];

const st = $input.first().json;
const route = $('Parse Intent & Route').first().json;
const spec = route.selected_specialist; let memText = ''; try { memText = $('Build Memory Context').first().json.memory_text || ''; } catch (e) {}
const sr = st.specialist_result;
const d = sr.data || {};
const evidence = (d.evidence && d.evidence.length) ? JSON.stringify(d.evidence).slice(0, 8000) : 'NONE (no matching record was found)';
let computed, rules;
if (spec === 'support_agent') {
  computed = JSON.stringify({ request_type: d.request_type || null, order_number: d.order_number || null, ticket_reference: d.ticket_reference || null, ticket_status: d.ticket_status || null });
  rules = 'BUSINESS RULES (support agent): The support agent must never invent order status, tracking numbers, delivery dates, refund status or any other fact. Every order number, status, total, tracking number and date in the answer must appear in VERIFIED EVIDENCE. If VERIFIED EVIDENCE is NONE the agent must say it could not find the order and ask the customer to check the order number. No refund policy is configured: the agent must never approve, deny, promise, or estimate the time or amount of a refund, and must never state refund eligibility; it may only say the request was recorded and passed to the team for review. For complaints the agent must be empathetic, must not promise compensation, and may say the complaint was recorded. A reference code that matches ticket_reference in SYSTEM-COMPUTED DATA is valid system-generated data. If the answer records a refund request or complaint and passes it to the human team, that is the correct behaviour: approve it and set needs_human=false, because the ticket already exists.';
} else if (spec === 'billing_agent') {
  computed = JSON.stringify({ request_type: d.request_type || null, ticket_reference: d.ticket_reference || null, ticket_status: d.ticket_status || null });
  rules = 'BUSINESS RULES (billing agent): The billing agent must never invent usage, amounts, invoice numbers, invoice status, subscription status, payment status or any billing fact. Every number, status, plan name, price, date and invoice detail in the answer must appear in VERIFIED EVIDENCE (data read from Stripe). A value shown as NOT AVAILABLE must be reported as unavailable, never guessed. A usage count of 0 is valid if VERIFIED EVIDENCE shows 0. The agent cannot change subscriptions, cancel plans, send invoices, apply credits or refunds: no authorization rules are configured. For such requests it may only say the request was recorded and passed to the team for review. A reference code that matches ticket_reference in SYSTEM-COMPUTED DATA is valid system-generated data. If the answer records a subscription change or invoice request and passes it to the human team, that is the correct behaviour: approve it, because the ticket already exists.';
} else {
  computed = JSON.stringify({ used_skus: d.used_skus || [], quote_id: d.quote_id || null, quote_total: d.quote_total || null, quote_issues: d.quote_issues || [] });
  rules = 'BUSINESS RULES (sales agent): the sales agent must never invent product information, prices, availability, discounts, specifications or quote values. No discounts or promotions exist in the data, so any discount or offer is invented. When information is missing the agent must say it does not have enough verified information. A truthful statement that the catalog lacks a requested item is acceptable when VERIFIED EVIDENCE really contains no matching product.';
}
const user = 'CUSTOMER MESSAGE:\n' + route.message + '\n\nSPECIALIST: ' + spec + '\n\nSPECIALIST ANSWER:\n' + (sr.response || '(none; specialist error: ' + sr.error + ')') + '\n\nSYSTEM-COMPUTED DATA:\n' + computed + '\n\nVERIFIED EVIDENCE (records from the database):\n' + evidence + '\n\nCUSTOMER MEMORY (background only):\n' + (memText || 'none');
const system = 'You are the quality reviewer (Supervisor) of a multi-agent business platform. You evaluate ONE specialist answer before it is sent to a customer. You receive: CUSTOMER MESSAGE, SPECIALIST ANSWER, SYSTEM-COMPUTED DATA and VERIFIED EVIDENCE (the database records the specialist could use). Check strictly: (1) relevant: the answer addresses the customer message. (2) sufficient: the answer is useful and complete, or it honestly says the information is unavailable. (3) supported: every price, availability, stock figure, specification, SKU, order number, status, tracking number, date and number in the answer appears in VERIFIED EVIDENCE or in SYSTEM-COMPUTED DATA. (4) no_hallucination: nothing invented, such as products, prices, stock, discounts, offers, free shipping, warranties, specifications, order facts or refund promises. (5) rules_followed: see BUSINESS RULES. ' + rules + ' MEMORY RULE: CUSTOMER MEMORY is background about earlier interactions of this same customer. A statement about earlier messages, orders or tickets of this customer is supported if it appears in CUSTOMER MEMORY, but memory is never a valid source for prices, stock, specifications, order status or tracking numbers. DECISION: approved=true only if all five checks pass. If any claim is unsupported by the evidence, approved=false. needs_retry=true if rewriting using only the evidence could fix the answer. needs_human=true if rewriting cannot fix it or the request is sensitive. confidence is your confidence in this evaluation, from 0 to 1. Return ONLY a JSON object: {"approved": boolean, "confidence": number, "reason": string, "needs_retry": boolean, "needs_human": boolean, "checks": {"relevant": boolean, "sufficient": boolean, "supported": boolean, "no_hallucination": boolean, "rules_followed": boolean}}.';
return [{ json: { attempt: st.attempt, specialist_result: sr, test_corrupted: st.test_corrupted, system_prompt: system, user_prompt: user } }];

const st = $('Test Hook 1 (test only)').first().json;
const ai = $input.first().json;
const sr = st.specialist_result;
const attempt = st.attempt;
const MAX = 2;
const MIN_CONF = 0.7;
let critique; let ok = false;
try {
  let c = ai.choices[0].message.content;
  c = String(c).replace(/```json|```/g, '').trim();
  const p = JSON.parse(c);
  critique = { approved: p.approved === true, confidence: Math.max(0, Math.min(1, Number(p.confidence) || 0)), reason: String(p.reason || '').slice(0, 800), needs_retry: p.needs_retry === true, needs_human: p.needs_human === true, checks: p.checks || {} };
  ok = typeof p.approved === 'boolean';
} catch (e) {
  critique = { approved: false, confidence: 0, reason: 'critique_unavailable: ' + String((ai.error && ai.error.message) || e.message).slice(0, 300), needs_retry: false, needs_human: true, checks: {} };
}
let decision, reason;
if (!sr.success) { decision = attempt < MAX ? 'retry' : 'escalate'; reason = 'specialist_failed: ' + (sr.error || 'unknown'); }
else if (!ok) { decision = 'escalate'; reason = critique.reason; }
else if (critique.approved && critique.confidence >= MIN_CONF && !critique.needs_human) { decision = 'approve'; reason = critique.reason; }
else if (critique.needs_human) { decision = 'escalate'; reason = 'reviewer_requested_human: ' + critique.reason; }
else if (attempt < MAX) { decision = 'retry'; reason = critique.reason; }
else { decision = 'escalate'; reason = 'still_insufficient_after_retry: ' + critique.reason; }
return [{ json: { attempt, decision, reason, critique_reason: critique.reason || reason, critique, specialist_result: sr, final_response: sr.response, confidence: critique.confidence, test_corrupted: st.test_corrupted === true } }];

const route = $('Parse Intent & Route').first().json;
const prev = $('Decide Action 1').first().json;
const ids = { sales_agent: 'YOUR_SALES_AGENT_WORKFLOW_ID', support_agent: 'YOUR_SUPPORT_AGENT_WORKFLOW_ID', billing_agent: 'YOUR_BILLING_AGENT_WORKFLOW_ID' };
const spec = route.selected_specialist;
return [{ json: { customer_id: route.customer_id, message: route.message, intent: route.intent, memory: $('Build Memory Context').first().json.memory_text || '', context: 'Reviewer feedback: ' + prev.critique_reason, attempt: 2, specialist: spec, workflow_id: ids[spec] } }];

