const d = $input.first().json;
const route = $('Parse Intent & Route').first().json;
const audit = $('Insert Audit Log').first().json;
const sr = d.specialist_result || {};
const sd = sr.data || {};
const needsHuman = sr.needs_human === true;
let mem = 0; try { mem = $('Build Memory Context').first().json.memory_count || 0; } catch (e) {}
const patch = { specialist_result: sr, critique: d.critique, confidence: d.confidence, retry_count: d.attempt - 1, needs_human: needsHuman, final_response: d.final_response, status: 'approved' };
const resp = { success: true, status: 'approved', response: d.final_response, intent: route.intent, specialist: route.selected_specialist, confidence: d.confidence, attempts: d.attempt, retried: d.attempt > 1, needs_human: needsHuman, ticket_reference: sd.ticket_reference || null, test_corrupted: d.test_corrupted === true, critique: { approved: d.critique.approved, reason: d.critique.reason }, audit_log_id: audit.id, memory_count: mem };
return [{ json: { audit_id: audit.id, supabase_url: route.supabase_url, patch_body: patch, response_body: resp } }];

const d = $input.first().json || {};
const route = $('Parse Intent & Route').first().json;
const audit = $('Insert Audit Log').first().json;
let reason, sr = null, critique = null, attempt = 0, conf = route.confidence;
if (d.decision === 'escalate') { reason = d.reason; sr = d.specialist_result; critique = d.critique; attempt = d.attempt; conf = d.confidence; }
else if (route.selected_specialist === 'human_escalation') { reason = 'routed_to_human: ' + route.routing_reason; }
else { reason = 'specialist_not_available: ' + route.selected_specialist + ' (not built yet)'; }
const msg = "Thank you. I've passed your request to our team and a human agent will follow up with you. / ধন্যবাদ। আপনার অনুরোধ আমাদের টিমকে জানানো হয়েছে, একজন প্রতিনিধি শীঘ্রই যোগাযোগ করবেন।";
return [{ json: { supabase_url: route.supabase_url, audit_id: audit.id,
  escalation_payload: { customer_id: route.customer_id, audit_log_id: audit.id, reason: String(reason).slice(0, 1000), status: 'open' },
  patch_body: { specialist_result: sr, critique, confidence: conf, retry_count: Math.max(0, attempt - 1), needs_human: true, final_response: msg, status: 'escalated' },
  response_body: { success: true, status: 'escalated', response: msg, reason, intent: route.intent, specialist: route.selected_specialist, attempts: attempt, audit_log_id: audit.id } } }];

const items = $input.all().map(i => i.json).filter(m => m && m.content && typeof m.similarity === 'number');
const top = items.slice(0, 5);
const memory_text = top.map(m => '- [' + String(m.created_at || '').slice(0, 10) + '] ' + String(m.content).slice(0, 500)).join('\n');
return [{ json: { memory_text, memory_count: top.length } }];

const route = $('Parse Intent & Route').first().json;
let outcome = 'escalated';
let approved = null, esc = null;
try { approved = $('Build Approved Response').first().json; } catch (e) {}
try { esc = $('Prepare Escalation').first().json; } catch (e) {}
if (approved && approved.audit_id) outcome = 'approved';
let row = null;
try {
  const date = new Date().toISOString().slice(0, 10);
  const msg = String(route.message).replace(/\s+/g, ' ').slice(0, 300);
  let type, content, meta;
  if (outcome === 'approved') {
    const rb = approved.response_body || {};
    const sd = ((approved.patch_body || {}).specialist_result || {}).data || {};
    const spec = rb.specialist;
    if (spec === 'support_agent') {
      type = sd.request_type || 'support_interaction';
      content = '[' + date + '] Customer message: "' + msg + '". Handled by support agent. Request type: ' + (sd.request_type || 'unknown') + '.' + (sd.order_number ? ' Order: ' + sd.order_number + '.' : '') + (sd.ticket_reference ? ' Ticket reference: ' + sd.ticket_reference + '.' : '') + ' Outcome: answered' + (rb.needs_human ? ', passed to human team.' : '.');
    } else if (spec === 'billing_agent') {
      type = sd.request_type || 'billing_interaction';
      content = '[' + date + '] Customer message: "' + msg + '". Handled by billing agent. Request type: ' + (sd.request_type || 'unknown') + '.' + (sd.ticket_reference ? ' Ticket reference: ' + sd.ticket_reference + '.' : '') + ' Outcome: answered' + (rb.needs_human ? ', passed to human team.' : '.');
    } else {
      type = 'sales_inquiry';
      content = '[' + date + '] Customer message: "' + msg + '". Handled by sales agent.' + ((sd.used_skus && sd.used_skus.length) ? ' Products discussed (SKU): ' + sd.used_skus.join(', ') + '.' : '') + (sd.quote_id ? ' Quote created: ' + sd.quote_id + '.' : '') + ' Outcome: answered.';
    }
    meta = { source_message_id: route.message_id, audit_log_id: approved.audit_id, specialist: spec, intent: route.intent, outcome: 'approved', order_number: sd.order_number || null, ticket_reference: sd.ticket_reference || null, used_skus: sd.used_skus || [] };
  } else {
    const rb = (esc && esc.response_body) || {};
    type = 'escalation';
    content = '[' + date + '] Customer message: "' + msg + '". Request was escalated to a human agent. Reason: ' + String(rb.reason || 'unknown').slice(0, 200);
    meta = { source_message_id: route.message_id, audit_log_id: esc ? esc.audit_id : null, specialist: route.selected_specialist, intent: route.intent, outcome: 'escalated' };
  }
  row = { customer_id: route.customer_id, memory_type: type, content, metadata: meta };
} catch (e) { row = null; }
return [{ json: { outcome, row, content: row ? row.content : null } }];

const ap = $('Build Approved Response').first().json;
const route = $('Parse Intent & Route').first().json;
